INSERT INTO `tbl_document_in` (`id`, `code`, `cate_id`, `number_in`, `date_in`, `number_dc`, `date_dc`, `title`, `content`, `source`, `user_id`, `user_share`, `is_publish`, `create_at`, `file`, `status`) VALUES
(2, 1730228688, 1, 1, '2024-10-28', '224/PGDĐT', '2024-10-28', 'Công văn về việc tổ chức hưởng ứng \"Ngày pháp luật Cộng hòa XHCNVN\" trong ngành Giáo dục và Đào tạo năm 2024', 'Thực hiện kế hoạc số 29/KH-UBND ngày 08/10/2024 của UBND thành phố Hà Nội về hưởng ứng \"Ngày pháp luật nước Cộng hòa xã hội chủ nghĩa Việt Nam\" trên địa bàn thành phố Hà Nội năm 2024', 'Phòng giáo dục Long Biên', 1, '', 1, '2024-10-30 09:49:44', '1730228688_document_in.pdf', 1),
(3, 1730257105, 13, 2, '2024-10-29', '184/LĐLĐ', '2024-10-23', 'Công văn về việc hỗ trợ nhà \"Mái ấm công đoàn\" năm 2025', 'Thực hiện ké hoạc sô 65/KH-LĐLĐ ngày 09/10/2024 của Liên đoàn lao động Thành phố Hà Nội về việc hỗ trợ nhà \"Mái ấm Công đoàn\" năm 2025. Ban thường vụ LĐLĐ quận Long Biên triển khai chương trình hỗ trợ nhà \"Mái ấm Công đoàn\" năm 2025', 'Liên đoàn lao động Long Biên', 7, '', 1, '2024-10-30 09:58:25', '1730257105_document_in.pdf', 1),
(4, 1730257389, 13, 3, '2024-10-29', '185/LĐLD', '2024-10-29', 'Công văn về việc phân bổ chi tiêu đoàn viên tham gia chương trình \"Chợ tết Công đoàn năm 2025\" trực tuyến của TLĐ', 'Thực hiện công văn số 925/LĐLĐ ngày 28 tháng 10 năm 2024 của Liên đoàn lao động thành phố Hà Nội về việc triển khai chương trình \"Chợ tết Công đoàn năm 2025\" trực tuyến của Tổng liên đoàn Lao động', 'Liên đoàn lao động Long Biên', 7, '', 1, '2024-10-30 10:03:09', '1730257389_document_in.pdf', 1),
(5, 1730257816, 14, 4, '2024-10-29', '2250/UBND-CA', '2024-10-29', 'Công văn về việc xử lý cán bộ, viên chức, công chức và chiến sỹ trong lực lượng vũ trang vi phạm quy định điều khiển phương tiện giao thông mà trong máu hoặc trong hơi thở có nồng độ cồn; không hợp tác với lực lượng chức năng trong xử lý vi phậm', '', 'Ủy ban nhân dân quận Long Biên', 7, '', 1, '2024-10-30 10:10:16', '1730257816_document_in.pdf', 1),
(6, 1730258045, 14, 5, '2024-10-29', '35/CT-TTg', '2024-09-17', 'Chỉ thị về việc xử lý cán bộ, công chức, viên chức và chiến sỹ trong lực lượng vũ trang vi phạm qui định điều khiển phương tiện giao thông mà trong máu hoặc hơi thở có nồng độ cồn; không hợp tác với lực lượng chức năng trong xử lí vi phạm', '', 'Văn phòng chính phủ', 7, '', 1, '2024-10-30 10:14:05', '1730258045_document_in.pdf', 1),
(7, 1730652108, 12, 6, '2024-10-30', '5383/KHLN-YT-GDĐT', '2024-10-30', 'Kế hoạch liên ngành thực hiện công tác Y tế trường học năm học 2024 - 2025', 'Thực hiện kế hoạch số 168/KH-UBND ngày 28/08/2018 của UBND Thành phố về phát triển thể lực,   tầm vóc  người Hà Nội đến năm 2030', 'Sở giáo dục và đào tạo Hà Nội', 7, '', 1, '2024-11-05 15:17:04', '1730652108_document_in.pdf', 1),
(8, 1730652466, 15, 7, '2024-10-31', '2231/UBND-YT', '2024-10-28', 'Công văn về việc triển khai đợt cao điểm truyền thông về ATTP trên địa bàn Quận trong quý IV/2024 và năm 2025', 'Thực hiện Kế hoạch số 302/KH0YBND ngày 22/10/2024 của UBND thành phố Hà Nội về cao điểm truyền thông về an toàn thực phẩm trên địa bàn thành phố Hà Nội giao đoạn 2024 - 2025', 'Ủy Ban Nhân Dân Quận Long Biên', 7, '', 1, '2024-11-05 15:20:04', '1730652466_document_in.pdf', 1),
(9, 1730652623, 4, 8, '2024-11-02', '228/PGDĐT', '2024-10-28', 'Công văn về việc hướng dẫn trọng tâm công tác tháng 11/2024 cấp Mầm Non', 'Thực hiện nhiệm vụ năm học 2024-2025 phòng giáo dục và đào tạo quận Long Biên hướng dẫn trọng tâm công tác tháng 11 năm 2024 cấp học Mầm non', 'Phòng giáo dục Long Biên', 7, '', 1, '2024-11-03 23:50:23', '1730652623_document_in.pdf', 1),
(10, 1730755959, 3, 9, '2024-11-04', '30/KH-PGDĐT', '2024-10-28', 'Kế  hoạch triển khai thực hiện chỉ thị số 30-CT/TU ngày 19/02/2024 của Ban thường vụ Thành ủy Hà Nội', 'Thực hiện Chỉ thị số 30-CT/TU ngày 19 tháng 2 năm 2024 của Ban thường vụ Thành ủy Hà Nội về việc \"Tăng cường sự lãnh đạo của cấp ủy Đảng về xây dựng người Hà Nội thanh lịch, văn minh\"', 'Phòng giáo dục Long Biên', 1, '', 1, '2024-11-05 04:32:39', '1730755959_document_in.pdf', 1),
(11, 1730756181, 10, 10, '2024-11-04', '431/KH-UBND', '2024-10-31', 'Kế hoạch tuyên dương các tập thể, các nhân tiêu biểu ngành GDĐT năm 2024; Chào mừng kỷ niệm 70 năm thành lập ngành GDĐT Hà Nội và 42 năm ngày Nhà giáo Việt Nam', 'UBND quận Long Biên  ban hành kế hoạch tổ chức Hội nghị tuyên dương khen thưởng các tập thể, các nhân tiêu biểu ngành GDĐT quận Long Biên năm 2024 chào mừng kỷ niệm 70 năm thành lập ngành GDĐT Thủ đô, kỷ niệm 42 năm ngày Nhà giáo Việt Nam', 'Ủy ban nhân dân quận Long Biên', 1, '', 1, '2024-11-05 04:36:21', '1730756181_document_in.pdf', 1),
(12, 1730793461, 14, 11, '2024-11-04', '03/HD-UBND-LĐLĐ', '2024-11-04', 'Hướng dẫn về việc tổ chức hội nghị cán bộ, công chức, viên chức, người lao động và hội nghị người lao động năm 2025', 'Hướng dẫn tổ chức hội nghị cán bộ, công chức., viên chức, người lao động và hội nghị người lao động năm 2025', 'Liên đoàn lao động quận Long Biên', 7, '2,3,4', 0, '2024-11-05 14:57:41', '1730793461_document_in.pdf', 1),
(13, 1731036989, 12, 12, '2024-11-07', '310/KH-UBND', '2024-10-28', 'Kế hoạch phát triển, nầng cấp, triển khai mở rộng nền tảng \"Công dân Thủ đô số\" - iHanoi trên đại bàn thành phố Hà Nội giai đoạn 2025-2026', 'Thực hiên nghị quyết số 18/NQ-TU ngày 30/12/2022 của Thành ủy về việc chuyển đổi số, xây dựng Thành phố Hà Nội thông minh đến năm 2025', 'Phòng nội vụ Long Biên', 7, '', 1, '2024-11-08 10:36:29', '1731036989_document_in.pdf', 1),
(14, 1731037184, 13, 13, '2024-11-07', '3218/STTTT-ATTT&GDĐT', '2024-10-28', 'Công văn về việc tham gia chiến dịch tuyên truyền Kỹ năng nhận diện và phòng chống lừa đảo trực tuyến  bảo vệ người dân trên không gian mạng năm 2024', '', 'Phòng giáo dục Long Biên', 7, '', 1, '2024-11-08 10:39:44', '1731037184_document_in.pdf', 1),
(15, 1731037347, 13, 14, '2024-11-07', '2336/UBND-TP', '2024-11-06', 'Công văn về việc tuyên truyền, phổ biến tài liệu giới thiệu luật Thủ đô số 39/2024/QH15', '', 'Phòng giáo dục Long Biên', 7, '', 1, '2024-11-08 10:42:27', '1731037347_document_in.pdf', 1),
